vi.mock('server-only', () => ({}));
const { calculateCouponDiscount, validateCouponCode } = await import('../../../task-a3-unit-tests/real/lib/coupons');
type Row = { id: string; code: string; name: string; description: null; discount_type: 'percentage' | 'fixed'; discount_value: number; minimum_amount: number; maximum_discount: number | null; usage_limit: number | null; usage_count: number | null; user_usage_limit: number | null; valid_from: string | null; valid_until: string | null; is_active: boolean; applies_to_product_id: null };
const row = (x: Partial<Row> = {}): Row => ({ id: 'c1', code: 'SAVE', name: 'Save', description: null, discount_type: 'fixed', discount_value: 1000, minimum_amount: 0, maximum_discount: null, usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: null, is_active: true, applies_to_product_id: null, ...x });
function db(data: Row | null, count = 0) { const cq: any = {}; cq.select = vi.fn(() => cq); cq.eq = vi.fn(() => cq); cq.maybeSingle = vi.fn().mockResolvedValue({ data, error: null }); let n = 0; const uq: any = {}; uq.select = vi.fn(() => uq); uq.eq = vi.fn(() => ++n === 2 ? Promise.resolve({ count, error: null }) : uq); const from = vi.fn((t: string) => t === 'coupons' ? cq : uq); return { client: { from } as any, from }; }
afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });
describe('A-3 iteration 2', () => {
  it('calculates percentage and price-capped fixed discounts', () => { expect(calculateCouponDiscount({ discount_type: 'percentage', discount_value: 20, maximum_discount: null }, 10000)).toBe(2000); expect(calculateCouponDiscount({ discount_type: 'fixed', discount_value: 15000, maximum_discount: null }, 10000)).toBe(10000); });
  it.each([['percentage', 50, 2000, 2000], ['percentage', 50, 0, 0], ['fixed', 5000, 2000, 2000], ['fixed', 5000, 0, 0]] as const)('caps %s coupons', (discount_type, discount_value, maximum_discount, expected) => { expect(calculateCouponDiscount({ discount_type, discount_value, maximum_discount }, 10000)).toBe(expected); });
  it.each([['   ', 'user-1', 400, '쿠폰 코드를 입력해주세요.'], ['SAVE', '', 401, '로그인이 필요합니다.']] as const)('guards input before DB', async (code, userId, status, error) => { const from = vi.fn(); expect(await validateCouponCode({ supabase: { from } as any, code, subtotal: 10000, userId })).toEqual({ error, status }); expect(from).not.toHaveBeenCalled(); });
  it('rejects missing and expired coupons', async () => { expect(await validateCouponCode({ supabase: db(null).client, code: 'SAVE', subtotal: 10000, userId: 'u1' })).toEqual({ error: '유효하지 않은 쿠폰 코드입니다.', status: 404 }); vi.useFakeTimers(); vi.setSystemTime(new Date('2026-08-17T12:00:00+09:00')); expect(await validateCouponCode({ supabase: db(row({ valid_until: '2026-08-16' })).client, code: 'SAVE', subtotal: 10000, userId: 'u1' })).toEqual({ error: '만료된 쿠폰입니다.', status: 400 }); });
  it('asserts both sides of the minimum boundary including the exact 9999 error', async () => { expect(await validateCouponCode({ supabase: db(row({ minimum_amount: 10000 })).client, code: 'SAVE', subtotal: 10000, userId: 'u1' })).toMatchObject({ discountAmount: 1000, finalAmount: 9000 }); expect(await validateCouponCode({ supabase: db(row({ minimum_amount: 10000 })).client, code: 'SAVE', subtotal: 9999, userId: 'u1' })).toEqual({ error: '최소 주문 금액 10,000원 이상이어야 합니다.', status: 400 }); });
  it('rejects a user at the usage limit', async () => { expect(await validateCouponCode({ supabase: db(row(), 1).client, code: 'SAVE', subtotal: 10000, userId: 'u1' })).toEqual({ error: '이미 사용 한도를 채운 쿠폰입니다.', status: 400 }); });
  it('uses real domain logic with strictly typed external fakes', async () => { const coupon: Coupon = { code: 'P20', type: 'PERCENTAGE', value: 20, minOrderAmount: 0, expiresAt: new Date('2026-12-31T00:00:00Z'), isActive: true }; const paymentGateway = { requestPayment: vi.fn().mockResolvedValue({ approved: true, approvedAmount: 8000 }) }; const orderRepository = { save: vi.fn(async (order: Order): Promise<Order> => order) }; const order = await createCouponOrder({ orderId: 'o1', productCode: 'P1', productPrice: 10000, couponCode: 'P20', now: new Date('2026-08-17T00:00:00Z'), couponRepository: { findByCode: vi.fn().mockResolvedValue(coupon) }, paymentGateway, orderRepository }); expect(paymentGateway.requestPayment).toHaveBeenCalledWith({ orderId: 'o1', amount: 8000 }); expect(order).toMatchObject({ discountAmount: 2000, status: 'PAID' }); });
});

