Given('계산 쿠폰은 {string}이고 할인값은 {int}이며 최대 한도는 {int}원이다', function(this: W, t: CouponDiscountType, v: number, cap: number) { this.calcCoupon = { discount_type: t, discount_value: v, maximum_discount: cap < 0 ? null : cap }; }); Given('DB에 쿠폰이 없다', function(this: W) { this.coupon = null; }); Given('검증 쿠폰은 {int}원 정액 할인이고 최소 주문금액은 {int}원이며 종료일은 {string}이다', function(this: W, value: number, minimum: number, until: string) { this.coupon = { id: 'c1', code: this.code, name: 'Save', description: null, discount_type: 'fixed', discount_value: value, minimum_amount: minimum, maximum_discount: null, usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: until, is_active: true, applies_to_product_id: null }; }); Given('사용자 사용 한도는 {int}회이고 사용 횟수는 {int}회이다', function(this: W, limit: number, count: number) { assert.ok(this.coupon); this.coupon.user_usage_limit = limit; this.usageCount = count; });
