Then('계산 할인 금액은 {int}원이다', function(this: W, v: number) { assert.equal(this.calculation, v); }); Then('할인 금액은 {int}원이다', function(this: W, v: number) { assert.ok(this.result && 'discountAmount' in this.result); assert.equal(this.result.discountAmount, v); }); Then('최종 결제 금액은 {int}원이다', function(this: W, v: number) { assert.ok(this.result && 'finalAmount' in this.result); assert.equal(this.result.finalAmount, v); }); Then('상태는 {int}이다', function(this: W, v: number) { assert.ok(this.result && 'status' in this.result); assert.equal(this.result.status, v); }); Then('실패 사유는 {string}이다', function(this: W, v: string) { assert.ok(this.result && 'error' in this.result); assert.equal(this.result.error, v); }); Then('DB 조회 횟수는 {int}회이다', function(this: W, v: number) { assert.equal(this.fromCalls, v); });

